`define CYCLE_TIME 20.0
`define PAT_NUM 1000
`define RAND_SEED 54243

module PATTERN(
    clk, 
    rst_n, 
    in_valid,
    in_data,
    out_valid,
    out_data
);

//---------------------------------------------------------------------
//   PORT DECLARATION
//---------------------------------------------------------------------
output logic clk; 
output logic rst_n;
output logic in_valid;
output logic in_data;
input  logic out_valid;
input  logic [15:0] out_data;

//================================================================
// clock
//================================================================
real CYCLE = `CYCLE_TIME;
initial begin
    clk = 1'b0;
    forever #(CYCLE/2.0) clk = ~clk;
end

//================================================================
// parameters & integer
//================================================================
integer PATNUM = `PAT_NUM;
integer SEED = `RAND_SEED;
integer i, j, k;
integer lat;
bit input_finish;
integer pat_cnt;

logic [7:0] input_data, prev_input_data, prev_prev_input_data;
logic [7:0] SPI_recv;
logic [7:0] record [100:0];

logic [15:0] golden;
logic [15:0] input_data_sum;

//================================================================
// initial
//================================================================
initial begin
    reset_task;
    repeat (PATNUM) begin
        repeat($urandom_range(4,9)) @(negedge clk);
        send_trans;
        wait_out_valid;
        check_ans;
        pass_single_pattern;
        pat_cnt = pat_cnt + 1;
    end
    YOU_PASS;
    $finish;
end

initial begin
    forever @(out_valid) begin
        if(out_valid === 1 & input_finish === 0) begin
            fail; 
            $display ("--------------------------------------------------------------------------------------------------------------------------------------------");
            $display ("                                                     FAIL!                                                            ");
            $display ("                              out_valid should not be asserted before input finish                                                            ");
            $display ("--------------------------------------------------------------------------------------------------------------------------------------------");
            #(3*CYCLE);
            $finish;
        end
    end
    forever @(negedge clk) begin
        if(out_valid === 0 & out_data !== 0) begin
            fail; 
            $display ("--------------------------------------------------------------------------------------------------------------------------------------------");
            $display ("                                                     FAIL!                                                            ");
            $display ("                                    out_data should be zero when out_valid is LOW                                                            ");
            $display ("--------------------------------------------------------------------------------------------------------------------------------------------");
            #(3*CYCLE);
            $finish;
        end
    end
end

//================================================================
// tasks
//================================================================
task pass_single_pattern; begin
    case($urandom_range(0,4))
        0: $display("\033[38;5;10mPATTERN NO.%5d PASS!!\033[0m", pat_cnt);
        1: $display("\033[38;5;11mPATTERN NO.%5d PASS!!\033[0m", pat_cnt);
        2: $display("\033[38;5;12mPATTERN NO.%5d PASS!!\033[0m", pat_cnt);
        3: $display("\033[38;5;13mPATTERN NO.%5d PASS!!\033[0m", pat_cnt);
        4: $display("\033[38;5;208mPATTERN NO.%5d PASS!!\033[0m", pat_cnt);
    endcase
end endtask

task reset_task; begin
	rst_n = 1'b1; 
    
	force clk = 1'b0;
	#(1.0*CYCLE); rst_n = 1'b0;
	#(2.0*CYCLE); 
    
	if(out_valid !== 1'b0 | out_data !== 16'h0000) begin
		fail; 
		$display ("--------------------------------------------------------------------------------------------------------------------------------------------");
		$display ("                                                     RESET FAIL!                                                            ");
        $display ("                                                      out_valid : %b                                                            ", out_valid);
        $display ("                                                      out_data : %h                                                            ", out_data);
		$display ("                                                Output should be reset                                                            ");
		$display ("--------------------------------------------------------------------------------------------------------------------------------------------");
		#(3*CYCLE);
		$finish;
	end

	rst_n = 1'b1; 
	in_valid = 1'b0; 
	in_data = 1'b0; 
    pat_cnt = 0;
	#(3.0*CYCLE); release clk; 
end endtask

task SPI_send_recv(input [7:0] in_data_);begin
    for(int i=7; i>=0; i=i-1) begin
        #(1.0);
        in_valid = 1'b1;
        in_data = in_data_[i];
        @(negedge clk);
    end
    in_data = 1'b0;
    in_valid = 1'b0;
end endtask

task send_trans; begin
    input_finish = 0;
    input_data_sum = 0;
    k = 0;
    while(!input_finish) begin
        prev_prev_input_data = prev_input_data;
        prev_input_data = input_data;
        input_data = $urandom_range(0,255);
        record[k] = input_data;
        repeat($urandom_range(1,5)) @(negedge clk);
        SPI_send_recv(input_data);               // send data
        // if(k !== 0) begin
        //     case(prev_input_data % 3)
        //         0: input_data_sum = input_data_sum + input_data + 255;
        //         1: input_data_sum = input_data_sum + input_data / 4;
        //         2: input_data_sum = input_data_sum + input_data * 2;
        //     endcase
        // end else begin
        //     input_data_sum = input_data_sum + input_data;
        // end
        input_data_sum = input_data_sum + input_data;
        k = k + 1;
        input_finish = k < 3 ? 0 : (input_data % 3 == 0 && prev_input_data % 3 == 0 && prev_prev_input_data % 3 == 0) | (input_data % 3 == 2 && prev_input_data % 3 == 1 && prev_prev_input_data % 3 == 0); 
    end
end endtask

task wait_out_valid; begin
    lat = 0;
    while(out_valid !== 1) begin
        lat = lat + 1;
        if (lat > 10) begin
            fail; 
            $display ("--------------------------------------------------------------------------------------------------------------------------------------------");
            $display ("                                           TIMEOUT! Latency over 10 cycles                                                            ");
            $display ("                                               Waiting for out_valid                                                            ");
            print_debug_info;
            $display ("--------------------------------------------------------------------------------------------------------------------------------------------");
            #(3*CYCLE);
            $finish;
        end
        @(negedge clk);
    end
end endtask

task print_debug_info; begin
    $display ("============================================================ DEBUG INFO ====================================================================");
        for(int j=0; j<k; j=j+1)
            if(j<10)
                $display ("                                                Data[%1d]:  %8b (%3d) mod 3 = %1d                                                           ", j, record[j], record[j], record[j] % 3);
            else
                $display ("                                                Data[%2d]: %8b (%3d) mod 3 = %1d                                                           ", j, record[j], record[j], record[j] % 3);
end endtask

task check_ans; begin
    golden = input_data_sum;
    if(out_data !== golden) begin
        fail; 
        $display ("--------------------------------------------------------------------------------------------------------------------------------------------");
        $display ("                                                     PATTERN NO. %5d FAIL!                                                            ", pat_cnt);
        $display ("                                                        Incorrect output data                                                            ");
        $display ("                                                          Expected: %d                                                            ", golden);
        $display ("                                                        Your output: %d                                                            ", out_data);
        print_debug_info;
        $display ("--------------------------------------------------------------------------------------------------------------------------------------------");
        #(3*CYCLE);
        $finish;
    end

    @(negedge clk);
    if(out_valid !== 1'b0) begin
        fail; 
        $display ("--------------------------------------------------------------------------------------------------------------------------------------------");
        $display ("                                                     FAIL!                                                            ");
        $display ("                                        out_valid should be HIGH for only 1 cycle                                                            ");
        $display ("--------------------------------------------------------------------------------------------------------------------------------------------");
        #(3*CYCLE);
        $finish;
    end
end endtask

